import {loadStore, jobStatus, requestStatus, match} from './state.js';
import {sectors, types, modes, skills} from './data.js';
const store=loadStore();
const app=document.querySelector('#app');
let ui={notice:'',error:'',filters:{},profileView:'owner',preview:null,jobStatusFilter:'',cvUrl:''};
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const path=()=>location.pathname.replace(/\/$/,'')||'/tacare';
const href=(p,label,cls='')=>`<a href="${p}" data-link class="${cls}">${label}</a>`;
const btn=(label,act,id='',cls='btn secondary',more='')=>`<button type="button" class="${cls}" data-action="${act}" data-id="${esc(id)}" ${more}>${label}</button>`;
const options=(list,value='',placeholder='Tất cả')=>`<option value="">${placeholder}</option>`+list.map(x=>`<option value="${esc(x)}" ${x===value?'selected':''}>${esc(x)}</option>`).join('');
const badge=(s,type='')=>`<span class="badge ${type||s}">${esc(s)}</span>`;
const panel=(title,body,cls='')=>`<section class="panel ${cls}"><h2>${title}</h2>${body}</section>`;
const field=(name,label,value='',required=false,type='text',hint='')=>`<div class="field"><label for="${name}">${label}${required?' <span aria-label="bắt buộc">*</span>':''}</label><input id="${name}" name="${name}" type="${type}" value="${esc(value)}" ${required?'required':''} ${hint?`aria-describedby="${name}-hint"`:''}><small id="${name}-hint">${hint}</small><small class="field-error" id="${name}-error"></small></div>`;
const select=(name,label,list,value='',required=false,placeholder='Chọn')=>`<div class="field"><label for="${name}">${label}${required?' <span aria-label="bắt buộc">*</span>':''}</label><select id="${name}" name="${name}" ${required?'required':''}>${options(list,value,placeholder)}</select><small class="field-error" id="${name}-error"></small></div>`;
const selectNamed=(name,label,items,value='',required=false)=>`<div class="field"><label for="${name}">${label}</label><select id="${name}" name="${name}" ${required?'required':''}><option value="">Chọn tin</option>${items.map(x=>`<option value="${esc(x.id)}" ${x.id===value?'selected':''}>${esc(x.title)}</option>`).join('')}</select><small class="field-error" id="${name}-error"></small></div>`;
const multiSkills=(name,label,selected=[])=>`<div class="field"><label for="${name}">${label}</label><select id="${name}" name="${name}" multiple size="7">${skills.map(x=>`<option value="${esc(x)}" ${selected.includes(x)?'selected':''}>${esc(x)}</option>`).join('')}</select><small>Giữ Ctrl/Cmd để chọn nhiều kỹ năng.</small><small class="field-error" id="${name}-error"></small></div>`;
const area=(name,label,value='',required=false)=>`<div class="field"><label for="${name}">${label}${required?' <span aria-label="bắt buộc">*</span>':''}</label><textarea id="${name}" name="${name}" rows="4" ${required?'required':''}>${esc(value)}</textarea><small class="field-error" id="${name}-error"></small></div>`;
const brand={khovieclam:{name:'Kho Việc Làm',domain:'khovieclam.vn',logo:'/assets/khovieclam.png'},tuhoso:{name:'Tủ Hồ Sơ',domain:'tuhoso.com',logo:'/assets/tuhoso.png'},tacare:{name:'TA.CARE',domain:'tacare.vn',logo:'/assets/tacare.png'}};
const root=()=>path().split('/')[1]||'tacare';
const me=()=>store.current();
const d=()=>store.get();
const org=id=>d().orgs.find(x=>x.id===id);
const user=id=>d().accounts.find(x=>x.id===id);
const job=id=>d().jobs.find(x=>x.id===id);
const profile=id=>d().profiles.find(x=>x.id===id);
const eligibleProfiles=()=>d().profiles.filter(p=>p.visible&&p.scope!=='private');
const myProfile=()=>profile(me().profileId);
const myJobs=()=>d().jobs.filter(j=>me().role==='admin'||j.orgId===me().orgId);
const myRequests=()=>d().requests.filter(r=>me().role==='admin'||r.senderId===me().id||r.receiverId===me().id);
const canJob=j=>me().role==='admin'||me().role==='business'&&j.orgId===me().orgId;
const date=v=>v?new Date(v+'T00:00:00').toLocaleDateString('vi-VN'):'';
function go(url){history.pushState({},'',url);ui.error='';ui.notice='';ui.preview=null;window.scrollTo(0,0);render();}
function message(txt,error=false){ui[error?'error':'notice']=txt;render();window.scrollTo(0,0);}
function safe(fn){try{fn();}catch(e){message(e.message,true);}}
function shell(body){const r=root(),b=brand[r]||brand.tacare,u=me(),unread=d().notifications.filter(n=>n.userId===u.id&&!n.read).length;
 const nav=r==='khovieclam'?[['/khovieclam','Giới thiệu'],['/khovieclam/opportunities','Tìm cơ hội'],...(u.role==='business'||u.role==='admin'?[['/khovieclam/dashboard','Bảng tin doanh nghiệp'],['/khovieclam/candidates','Hồ sơ phù hợp'],['/khovieclam/requests','Đề nghị']]:[['/tuhoso/dashboard','Hồ sơ của tôi']])]:r==='tuhoso'?[['/tuhoso','Giới thiệu'],...(u.role==='candidate'?[['/tuhoso/dashboard','Tổng quan hồ sơ'],['/tuhoso/profile','Hồ sơ của tôi'],['/tuhoso/opportunities','Cơ hội gợi ý'],['/tuhoso/requests','Lời mời & đề nghị']]:[['/khovieclam/opportunities','Xem cơ hội']])]:[['/tacare','Hệ sinh thái'],['/tacare/dashboard','Tổng quan'],['/tacare/matching','Phù hợp'],['/tacare/connections','Kết nối'],['/tacare/notifications','Thông báo'+(unread?` (${unread})`:'')]];
 app.innerHTML=`<div class="app theme-${r}"><div class="demo-strip"><span>BẢN THỬ LOCAL · DỮ LIỆU HƯ CẤU</span><div class="demo-tools"><label for="demo-user">Xem với tài khoản</label><select id="demo-user" aria-label="Đổi tài khoản demo">${d().accounts.map(a=>`<option value="${a.id}" ${a.id===u.id?'selected':''}>${esc(a.name)} · ${a.role==='business'?'Doanh nghiệp':a.role==='candidate'?'Ứng viên':'Vận hành'}</option>`).join('')}</select>${btn('Khôi phục dữ liệu mẫu','reset','','text-button')}</div></div><header class="site-header"><div class="container nav-wrap">${href('/'+r,`<img class="logo ${r}" src="${b.logo}" alt="Logo ${b.name}"><span class="brand-copy"><strong>${b.name}</strong><small>${b.domain}</small></span>`,'brand')}<nav aria-label="Điều hướng chính">${nav.map(([url,label])=>href(url,label,path()===url?'active':'')).join('')}</nav><div class="site-switch">${Object.entries(brand).filter(([key])=>key!==r).map(([key,v])=>href('/'+key,`<span>${v.name}</span>`, 'switch-link')).join('')}</div></div></header><main id="main" class="container" tabindex="-1">${ui.error?`<div class="alert error" role="alert">${esc(ui.error)}</div>`:''}${ui.notice?`<div class="alert success" role="status">${esc(ui.notice)}</div>`:''}${body}</main><footer><div class="container footer-grid"><p><strong>${b.name}</strong><br>Bản thử trải nghiệm TA.CARE. Mọi thông tin và tổ chức là dữ liệu mẫu.</p><p>Điều hướng: ${href('/khovieclam','Kho Việc Làm')} · ${href('/tuhoso','Tủ Hồ Sơ')} · ${href('/tacare','TA.CARE')}</p></div></footer></div>`;
}
function hero(eyebrow,title,desc,actions,art){return `<section class="hero"><div><p class="eyebrow">${eyebrow}</p><h1>${title}</h1><p class="lead">${desc}</p><div class="actions">${actions}</div></div><div class="hero-art">${art}</div></section>`;}
function metric(n,label){return `<div class="metric"><strong>${n}</strong><span>${label}</span></div>`;}
function jobCard(j,compact=false){return `<article class="job-card"><div class="card-top"><span class="eyebrow">${esc(j.sector)}</span>${badge(jobStatus(j.status),j.status)}</div><h3>${href('/khovieclam/opportunity/'+j.id,esc(j.title))}</h3><p class="muted">${esc(org(j.orgId)?.name)} · ${esc(j.location)} · ${esc(j.mode)}</p><div class="tag-list">${[...j.required.slice(0,3),j.type].map(x=>`<span class="tag">${esc(x)}</span>`).join('')}</div>${compact?'':`<div class="card-bottom"><span>Hạn ${date(j.deadline)}</span>${href('/khovieclam/opportunity/'+j.id,'Xem chi tiết →','inline-link')}</div>`}</article>`;}
function profileCard(p,j){const m=j?match(j,p):null;return `<article class="person-card"><div class="avatar">${esc(p.name.split(' ').slice(-2).map(s=>s[0]).join(''))}</div><div><p class="eyebrow">${esc(p.sector||'Chưa chọn lĩnh vực')}</p><h3>${href('/tuhoso/profile/'+p.id,esc(p.name))}</h3><p class="muted">${esc(p.headline)} · ${esc(p.location)}</p><div class="tag-list">${p.skillItems.slice(0,4).map(s=>`<span class="tag">${esc(s.name)}</span>`).join('')}</div></div>${m?`<div class="score"><strong>${m.score}</strong><small>Điểm phù hợp<br>mô phỏng</small></div>`:''}</article>`;}
function homeJobs(){const jobs=d().jobs.filter(j=>j.status==='published');return hero('KHO CƠ HỘI / KHOVIECLAM.VN','Tìm việc phù hợp với điều bạn đang có.','Khám phá việc làm, thực tập, dự án và task. Mỗi tin cho biết việc cần làm, kỹ năng cần có và bước tiếp theo.',`${href('/khovieclam/opportunities','Khám phá cơ hội','btn primary')}${href('/khovieclam/dashboard','Quản lý tin tuyển dụng','btn secondary')}`,`<div class="shelf"><div class="shelf-head"><span>Danh mục nổi bật</span><strong>${jobs.length} cơ hội đang hiển thị</strong></div>${sectors.slice(0,5).map((s,i)=>`<button type="button" class="shelf-row" data-action="sector" data-id="${esc(s)}"><span>0${i+1}</span><strong>${s}</strong><span>→</span></button>`).join('')}</div>`)+`<section class="section-heading"><div><p class="eyebrow">MỞ CHO BẠN</p><h2>Cơ hội mới để bắt đầu</h2></div>${href('/khovieclam/opportunities','Xem toàn bộ →','inline-link')}</section><div class="cards three">${jobs.slice(0,3).map(j=>jobCard(j)).join('')}</div>`;}
function listJobs(){const f=ui.filters;let arr=d().jobs.filter(j=>j.status==='published');arr=arr.filter(j=>(!f.q||`${j.title} ${j.description} ${org(j.orgId)?.name}`.toLowerCase().includes(f.q.toLowerCase()))&&(!f.sector||j.sector===f.sector)&&(!f.type||j.type===f.type)&&(!f.mode||j.mode===f.mode)&&(!f.experience||j.experience===f.experience)&&(!f.skill||[...j.required,...j.preferred].includes(f.skill)));
 return `<div class="page-head"><p class="eyebrow">KHO VIỆC LÀM</p><h1>Khám phá cơ hội</h1><p>Chọn điều phù hợp với thời gian, nơi làm việc và kỹ năng của bạn.</p></div><div class="list-layout"><aside class="filter-panel"><h2>Bộ lọc</h2><form id="job-filters">${field('q','Từ khóa',f.q||'')}${select('sector','Lĩnh vực',sectors,f.sector,'','Tất cả lĩnh vực')}${select('type','Loại cơ hội',types,f.type,'','Tất cả loại')}${select('mode','Hình thức làm việc',modes,f.mode,'','Tất cả hình thức')}${select('experience','Kinh nghiệm',['Không yêu cầu','Dưới 1 năm','1–2 năm'],f.experience,'','Tất cả mức')}${select('skill','Kỹ năng',skills,f.skill,'','Tất cả kỹ năng')}<div class="actions"><button class="btn primary" type="submit">Áp dụng bộ lọc</button>${btn('Xóa bộ lọc','clear-filters')}</div></form></aside><div><div class="result-head"><h2>${arr.length} cơ hội</h2><span class="muted">Dữ liệu mẫu · cập nhật theo bộ lọc</span></div>${arr.length?`<div class="cards two">${arr.map(j=>jobCard(j)).join('')}</div>`:`<div class="empty"><h3>Chưa có cơ hội phù hợp</h3><p>Hãy thử bỏ bớt điều kiện để xem thêm tin.</p>${btn('Xóa bộ lọc','clear-filters','','btn primary')}</div>`}</div></div>`;}
function detailJob(id){const j=job(id);if(!j)return notFound();const u=me(),owner=canJob(j),myP=u.role==='candidate'?myProfile():null;return `<div class="crumb">${href('/khovieclam/opportunities','Cơ hội')} / ${esc(j.title)}</div><div class="detail-layout"><div><div class="page-head compact"><p class="eyebrow">${esc(j.sector)} · ${esc(j.type)}</p><h1>${esc(j.title)}</h1><p>${esc(org(j.orgId)?.name)} · ${esc(j.location)} · ${esc(j.mode)}</p><div class="tag-list">${badge(jobStatus(j.status),j.status)}${j.required.map(x=>`<span class="tag">${esc(x)}</span>`).join('')}</div></div>${panel('Bạn sẽ làm gì?',`<p>${esc(j.description)}</p><p><strong>Kết quả mong đợi:</strong> ${esc(j.outcome||'Trao đổi khi kết nối.')}</p>`)}${panel('Kỹ năng và điều kiện',`<p><strong>Bắt buộc:</strong> ${esc(j.required.join(', ')||'Chưa chọn')}</p><p><strong>Ưu tiên:</strong> ${esc(j.preferred?.join(', ')||'Không có')}</p><p><strong>Kinh nghiệm:</strong> ${esc(j.experience)}</p>`)}${myP?panel('Vì sao có thể phù hợp?',matchPanel(j,myP)):''}</div><aside class="detail-aside">${panel('Thông tin cơ hội',`<dl><dt>Đơn vị đăng</dt><dd>${esc(org(j.orgId)?.name)}</dd><dt>Thời gian</dt><dd>${esc(j.schedule)}</dd><dt>Bắt đầu</dt><dd>${date(j.start)}</dd><dt>Hạn nhận đề nghị</dt><dd>${date(j.deadline)}</dd><dt>Số lượng</dt><dd>${esc(j.quantity)}</dd><dt>Thù lao</dt><dd>${esc(j.pay)}</dd></dl><div class="actions vertical">${u.role==='candidate'&&j.status==='published'?href('/tuhoso/apply/'+j.id,'Gửi đề nghị ứng tuyển','btn primary'):''}${owner?href('/khovieclam/job/'+j.id+'/edit','Sửa tin','btn secondary'):''}${u.role==='business'&&owner&&j.status==='published'?href('/tacare/matching?job='+j.id,'Xem hồ sơ phù hợp','btn secondary'):''}</div>`)}</aside></div>`;}
function matchPanel(j,p){const m=match(j,p);return `<div class="match-panel"><div class="score large"><strong>${m.score}</strong><small>Điểm phù hợp<br>mô phỏng</small></div><div><p><strong>Đã có:</strong> ${esc(m.matched.join(', ')||'Chưa có kỹ năng bắt buộc')}</p><p><strong>Còn thiếu:</strong> ${esc(m.missing.join(', ')||'Không thiếu kỹ năng bắt buộc')}</p><p><strong>Ưu tiên đã có:</strong> ${esc(m.extra.join(', ')||'Chưa có')}</p><p><strong>Thời gian/địa điểm:</strong> ${m.sameMode?'Hình thức phù hợp':'Hình thức cần trao đổi'} · ${m.sameLocation?'Địa điểm phù hợp':'Địa điểm cần trao đổi'}</p>${m.incomplete?'<p class="muted">Hồ sơ còn thiếu dữ liệu hình thức hoặc địa điểm.</p>':''}</div></div><p class="fine">Điểm giúp đối chiếu thông tin, không phải xác suất được tuyển. Hai bên tự quyết định việc trao đổi.</p>`;}
function dashboardJobs(){if(!['business','admin'].includes(me().role))return access('Bảng tin dành cho tài khoản doanh nghiệp.');const list=myJobs(),shown=list.filter(j=>!ui.jobStatusFilter||j.status===ui.jobStatusFilter),requests=myRequests().filter(r=>r.receiverId===me().id||r.senderId===me().id);return `<div class="page-head"><p class="eyebrow">KHÔNG GIAN DOANH NGHIỆP</p><h1>Quản lý nhu cầu công việc</h1><p>Đăng tin rõ ràng, xem đề nghị và chủ động mời ứng viên phù hợp.</p><div class="actions">${href('/khovieclam/job/new','Tạo tin mới','btn primary')}${href('/tacare/connections','Xem đề nghị và lời mời','btn secondary')}</div></div><div class="metrics">${metric(list.filter(j=>j.status==='published').length,'Đang hiển thị')}${metric(list.filter(j=>j.status==='draft').length,'Bản nháp')}${metric(list.filter(j=>j.status==='paused').length,'Tạm ngừng')}${metric(requests.filter(r=>r.status==='pending').length,'Kết nối đang chờ')}</div>${panel('Tin của tổ chức',`<div class="status-tabs" aria-label="Lọc trạng thái tin">${[['','Tất cả'],['draft','Nháp'],['published','Đang hiển thị'],['paused','Tạm ngừng'],['closed','Đã đóng']].map(([key,label])=>btn(label,'job-filter',key,ui.jobStatusFilter===key?'tab active':'tab')).join('')}</div><div class="table-wrap"><table><thead><tr><th>Vị trí</th><th>Loại</th><th>Trạng thái</th><th>Thao tác</th></tr></thead><tbody>${shown.map(j=>`<tr><td>${href('/khovieclam/opportunity/'+j.id,esc(j.title))}<small>${esc(j.location)}</small></td><td>${esc(j.type)}</td><td>${badge(jobStatus(j.status),j.status)}</td><td><div class="row-actions">${href('/khovieclam/job/'+j.id+'/edit','Sửa')}${j.status==='draft'?btn('Đăng','job-status',j.id,'link-button',`data-status="published"`):''}${j.status==='published'?btn('Tạm ngừng','job-status',j.id,'link-button',`data-status="paused"`):''}${j.status==='paused'?btn('Mở lại','job-status',j.id,'link-button',`data-status="published"`):''}${['published','paused'].includes(j.status)?btn('Đóng','job-status',j.id,'link-button',`data-status="closed"`):''}${j.status==='draft'?btn('Xóa','job-status',j.id,'link-button danger',`data-status="deleted"`):''}</div></td></tr>`).join('')}</tbody></table></div>${!shown.length?'<p class="muted">Chưa có tin ở trạng thái này.</p>':''}`)}`;}
function jobForm(id){if(!['business','admin'].includes(me().role))return access('Chỉ doanh nghiệp được tạo hoặc sửa tin.');const old=id&&id!=='new'?job(id):null;if(old&&!canJob(old))return access('Tin thuộc tổ chức khác.');if(old?.status==='closed')return access('Tin đã đóng chỉ được xem lại.');const j=ui.preview||old||{title:'',sector:'',type:'',mode:'Kết hợp',location:'Hà Nội',experience:'Không yêu cầu',schedule:'',start:'',deadline:'',quantity:1,pay:'',description:'',outcome:'',required:[],preferred:[]};return `<div class="crumb">${href('/khovieclam/dashboard','Tin của tôi')} / ${old?'Sửa tin':'Tạo tin'}</div><div class="page-head compact"><p class="eyebrow">BIÊN TẬP CƠ HỘI</p><h1>${old?'Sửa tin':'Tạo tin mới'}</h1><p>Bắt đầu bằng bản nháp. Trường có dấu * cần đủ trước khi đăng.</p></div>${ui.preview?`<div class="preview-banner"><strong>Xem trước tin</strong><p>${esc(ui.preview.title||'Chưa có tiêu đề')} · ${esc(ui.preview.type||'Chưa chọn loại')} · ${esc(ui.preview.location||'Chưa có địa điểm')}</p>${btn('Quay lại sửa','back-preview')}</div>`:''}<form id="job-form" data-id="${old?.id||''}" novalidate><div class="form-grid">${field('title','Tên cơ hội',j.title,true)}${select('sector','Lĩnh vực',sectors,j.sector,true)}${select('type','Loại cơ hội',types,j.type,true)}${select('mode','Hình thức làm việc',modes,j.mode,true)}${field('location','Địa điểm',j.location,true)}${select('experience','Kinh nghiệm',['Không yêu cầu','Dưới 1 năm','1–2 năm'],j.experience,true)}${field('schedule','Lịch/thời lượng',j.schedule)}${field('start','Ngày bắt đầu',j.start,false,'date')}${field('deadline','Hạn nhận đề nghị',j.deadline,true,'date')}${field('quantity','Số lượng',j.quantity,false,'number')}${field('pay','Thù lao/khoảng lương',j.pay)}${field('outcome','Đầu ra mong đợi',j.outcome)}</div>${area('description','Nhiệm vụ và mô tả',j.description,true)}<div class="form-grid">${multiSkills('required','Kỹ năng bắt buộc *',j.required)}${multiSkills('preferred','Kỹ năng ưu tiên',j.preferred)}</div><p class="fine">Chọn nhiều kỹ năng từ danh mục dùng chung; kỹ năng bắt buộc cần ít nhất một mục khi đăng.</p><div class="actions"><button type="submit" name="intent" value="draft" class="btn secondary">Lưu nháp</button><button type="submit" name="intent" value="preview" class="btn secondary">Xem trước</button><button type="submit" name="intent" value="publish" class="btn primary">Đăng tin</button>${href('/khovieclam/dashboard','Hủy','btn text-button')}</div></form>`;}
function candidateSearch(){if(!['business','admin'].includes(me().role))return access('Hồ sơ phù hợp dành cho doanh nghiệp.');const j=myJobs().find(x=>x.status==='published'),profiles=eligibleProfiles();return `<div class="page-head"><p class="eyebrow">HỒ SƠ ĐƯỢC CHIA SẺ</p><h1>Tìm người phù hợp</h1><p>Chỉ hiển thị phần hồ sơ ứng viên đã cho phép. Thông tin liên hệ được giữ riêng.</p></div><div class="cards two">${profiles.map(p=>profileCard(p,j)).join('')}</div>${!profiles.length?'<div class="empty">Chưa có hồ sơ đang hiển thị.</div>':''}`;}
function homeProfile(){return hero('HỒ SƠ NĂNG LỰC / TUHOSO.COM','Mỗi bước bạn đi qua đều có giá trị.','Bắt đầu bằng điều bạn biết và mong muốn. Kỹ năng, sản phẩm và minh chứng có thể bổ sung dần khi bạn phát triển.',`${href('/tuhoso/dashboard','Mở hồ sơ của tôi','btn primary')}${href('/tuhoso/register','Tạo tài khoản demo','btn secondary')}`,`<div class="folio"><div class="folio-tab">01 / BẠN LÀ AI</div><div class="folio-tab">02 / BẠN BIẾT GÌ</div><div class="folio-tab">03 / BẠN ĐÃ LÀM</div><div class="folio-tab">04 / BẠN MUỐN GÌ</div><div class="folio-mark">Hồ sơ của bạn, theo nhịp của bạn.</div></div>`)+`<section class="section-heading"><div><p class="eyebrow">XÂY DỰNG DẦN</p><h2>Một hồ sơ sống, luôn có thể cập nhật</h2></div></section><div class="steps"><div><span>01</span><h3>Giới thiệu bản thân</h3><p>Học vấn, định hướng và thời gian sẵn sàng.</p></div><div><span>02</span><h3>Thêm kỹ năng</h3><p>Ghi rõ bạn đã dùng kỹ năng trong việc gì.</p></div><div><span>03</span><h3>Chọn cách chia sẻ</h3><p>Bạn kiểm soát phần thông tin người khác nhìn thấy.</p></div></div>`;}
function register(){return `<div class="page-head compact"><p class="eyebrow">TÀI KHOẢN MẪU</p><h1>Bắt đầu hồ sơ demo</h1><p>Chỉ nhập tên hiển thị. Không dùng mật khẩu hoặc thông tin cá nhân thật.</p></div><form id="register-form" class="panel narrow" novalidate>${field('name','Tên hiển thị','',true)}<div class="actions"><button class="btn primary">Tạo hồ sơ demo</button>${href('/tuhoso','Quay lại','btn secondary')}</div></form>`;}
function profileDashboard(){if(me().role!=='candidate')return access('Hồ sơ cá nhân dành cho ứng viên.');const p=myProfile(),filled=[p.education,p.sector,p.goal,p.availability,p.skillItems.length,p.evidence.length].filter(Boolean).length,invites=myRequests().filter(r=>r.receiverId===me().id&&r.type==='invitation'),suggestions=d().jobs.filter(j=>j.status==='published').sort((a,b)=>match(b,p).score-match(a,p).score).slice(0,3);return `<div class="page-head"><p class="eyebrow">TỦ HỒ SƠ / TỔNG QUAN</p><h1>Xin chào, ${esc(p.name)}</h1><p>Hồ sơ có thể bắt đầu từ ít thông tin. Hoàn thiện dần để hiểu cơ hội rõ hơn.</p><div class="actions">${href('/tuhoso/profile/edit','Cập nhật hồ sơ','btn primary')}${href('/tuhoso/profile','Xem hồ sơ','btn secondary')}</div></div><div class="metrics">${metric(Math.round(filled/6*100)+'%','Đã bổ sung')}${metric(p.skillItems.length,'Kỹ năng')}${metric(p.evidence.length,'Minh chứng')}${metric(invites.filter(r=>r.status==='pending').length,'Lời mời đang chờ')}</div><div class="dashboard-grid">${panel('Bước tiếp theo',`<ul class="link-list"><li>${href('/tuhoso/profile/edit',p.education?'Cập nhật học vấn và mục tiêu':'Bổ sung học vấn và mục tiêu')}</li><li>${href('/tuhoso/skills','Thêm kỹ năng đã sử dụng')}</li><li>${href('/tuhoso/sharing','Chọn cách chia sẻ hồ sơ')}</li><li>${href('/tacare/connections','Xem lời mời và đề nghị')}</li></ul>`)}${panel('Quyền chia sẻ',`<p>${p.visible?'Hồ sơ đang được tìm thấy':'Hồ sơ đang tạm ẩn'} · Phạm vi: ${esc(scopeLabel(p.scope))}</p><p class="muted">Liên hệ ${p.shareContact?'có thể chia sẻ sau khi đồng ý trao đổi':'đang được giữ riêng'}.</p>${href('/tuhoso/sharing','Điều chỉnh chia sẻ →','inline-link')}`)}</div><section class="section-heading"><div><p class="eyebrow">CÓ THỂ BẠN QUAN TÂM</p><h2>Cơ hội gợi ý</h2></div>${href('/tuhoso/opportunities','Xem thêm →','inline-link')}</section><div class="cards three">${suggestions.map(j=>jobCard(j,true)).join('')}</div>`;}
const scopeLabel=s=>({public:'Công khai',members:'Thành viên',private:'Riêng tư'})[s]||s;
function profilePage(id){const p=id?profile(id):me().role==='candidate'?myProfile():null;if(!p)return access('Chọn tài khoản ứng viên để xem hồ sơ của mình.');const owner=me().role==='candidate'&&me().profileId===p.id;const permitted=owner||me().role==='admin'||p.visible&&p.scope!=='private';if(!permitted)return access('Hồ sơ này không đang được chia sẻ.');const publicView=(!owner||ui.profileView==='public');if(owner&&publicView&&(!p.visible||p.scope==='private'))return `<div class="page-head compact"><h1>Hồ sơ đang được giữ riêng</h1><p>Người khác sẽ không thấy nội dung này khi hồ sơ tạm ẩn hoặc đặt riêng tư.</p>${btn('Quay về chế độ chủ hồ sơ','toggle-preview','','btn primary')}</div>`;return `<div class="crumb">${href('/tuhoso/dashboard','Tủ Hồ Sơ')} / ${esc(p.name)}</div><div class="profile-cover"><div class="avatar big">${esc(p.name.split(' ').slice(-2).map(s=>s[0]).join(''))}</div><div><p class="eyebrow">HỒ SƠ NĂNG LỰC</p><h1>${esc(p.name)}</h1><p>${esc(p.headline)} · ${esc(p.location||'Chưa chọn địa điểm')}</p></div>${owner?`<div class="actions">${btn(publicView?'Quay về chế độ chủ hồ sơ':'Xem như người được chia sẻ','toggle-preview','','btn secondary')}${href('/tuhoso/profile/edit','Sửa hồ sơ','btn primary')}</div>`:''}</div>${publicView?`<p class="notice-inline">Đang xem phần hồ sơ được phép chia sẻ. Email và liên hệ không công khai.</p>`:''}${owner&&!publicView?panel('Thông tin riêng của bạn',`<p><strong>Email:</strong> ${esc(p.email||'Chưa nhập')}</p><p><strong>CV mẫu:</strong> ${esc(p.cvName||'Chưa chọn')}</p>`):''}<div class="detail-layout"><div>${panel('Về tôi',`<p>${esc(p.goal||'Chưa có phần giới thiệu.')}</p><p><strong>Học vấn:</strong> ${esc(p.education||'Chưa bổ sung')}</p><p><strong>Lĩnh vực:</strong> ${esc(p.sector||'Chưa chọn')}</p>`)}${panel('Kỹ năng',`<div class="skill-list">${p.skillItems.map(s=>`<div><strong>${esc(s.name)}</strong><span>${esc(s.level)} · ${esc(s.use||'Chưa mô tả cách dùng')}</span></div>`).join('')||'<p>Chưa bổ sung kỹ năng.</p>'}</div>${owner?href('/tuhoso/skills','Quản lý kỹ năng →','inline-link'):''}`)}${panel('Dự án và minh chứng',`${p.evidence.map(e=>`<article class="evidence"><span class="eyebrow">${esc(evidenceLabel(e.status))}</span><h3>${esc(e.title)}</h3><p>${esc(e.role)} · ${esc(e.result||e.description||'')}</p>${e.url?`<p class="muted">Liên kết minh chứng: ${esc(e.url)}</p>`:''}</article>`).join('')||'<p>Chưa có minh chứng. Hồ sơ vẫn có thể dùng để tìm cơ hội.</p>'}${owner?href('/tuhoso/evidence','Quản lý minh chứng →','inline-link'):''}`)}</div><aside class="detail-aside">${panel('Sẵn sàng tham gia',`<dl><dt>Hình thức</dt><dd>${esc(p.mode||'Chưa chọn')}</dd><dt>Lịch</dt><dd>${esc(p.availability||'Chưa cập nhật')}</dd><dt>Thù lao mong muốn</dt><dd>${esc(p.pay||'Trao đổi sau')}</dd></dl>${owner?href('/tuhoso/sharing','Cài đặt chia sẻ →','inline-link'):''}`)}${!owner&&me().role==='business'?panel('Kết nối',`<p>Chọn tin đang hiển thị của tổ chức để gửi lời mời.</p><form id="invite-form" data-profile="${p.id}">${selectNamed('jobId','Tin của tổ chức',myJobs().filter(j=>j.status==='published'),'',true)}${area('message','Lời nhắn','Mời bạn trao đổi về cơ hội này.')}<button class="btn primary">Mời trao đổi</button></form>`):''}</aside></div>`;}
const evidenceLabel=s=>({unverified:'Chưa xác minh',pending:'Chờ xác minh',verified:'Đã xác minh',declined:'Từ chối'})[s]||s;
function editProfile(){if(me().role!=='candidate')return access('Chỉ ứng viên sửa được hồ sơ của mình.');const p=myProfile();return `<div class="crumb">${href('/tuhoso/profile','Hồ sơ')} / Chỉnh sửa</div><div class="page-head compact"><p class="eyebrow">THÔNG TIN CỦA BẠN</p><h1>Cập nhật hồ sơ</h1><p>Thông tin có thể thay đổi theo hành trình của bạn.</p></div><form id="profile-form" novalidate><div class="form-grid">${field('name','Tên hiển thị',p.name,true)}${field('headline','Dòng giới thiệu',p.headline)}${field('education','Học vấn / chuyên ngành',p.education)}${select('sector','Lĩnh vực quan tâm',sectors,p.sector)}${field('location','Khu vực làm việc',p.location)}${select('mode','Hình thức mong muốn',modes,p.mode)}${field('availability','Lịch sẵn sàng',p.availability)}${field('pay','Thù lao mong muốn (tùy chọn)',p.pay)}</div>${area('goal','Mục tiêu phát triển',p.goal)}<div class="actions"><button class="btn primary">Lưu hồ sơ</button>${href('/tuhoso/profile','Hủy','btn secondary')}</div></form>`;}
function skillsPage(){if(me().role!=='candidate')return access('Chỉ ứng viên quản lý kỹ năng.');const p=myProfile();return `<div class="page-head compact"><p class="eyebrow">HỒ SƠ / KỸ NĂNG</p><h1>Kỹ năng của bạn</h1><p>Ghi lại kỹ năng và cách bạn đã dùng. Có thể bổ sung minh chứng sau.</p></div><div class="detail-layout"><div>${panel('Đã thêm',`<div class="skill-list">${p.skillItems.map(s=>`<div><strong>${esc(s.name)}</strong><span>${esc(s.level)} · ${esc(s.use)}</span>${btn('Sửa','edit-skill',s.name,'link-button')}${btn('Xóa','remove-skill',s.name,'link-button danger')}</div>`).join('')||'<p>Chưa có kỹ năng.</p>'}</div>`)}</div><aside>${panel('Thêm kỹ năng',`<form id="skill-form">${select('name','Kỹ năng',skills,'',true)}${select('level','Mức độ',['Mới học','Cơ bản','Khá','Thành thạo'],'Cơ bản',true)}${field('use','Đã dùng trong việc gì?','')}<button class="btn primary">Thêm kỹ năng</button></form>`)}</aside></div>${href('/tuhoso/evidence','Tiếp tục: Minh chứng →','inline-link')}`;}
function evidencePage(){if(me().role!=='candidate')return access('Chỉ ứng viên quản lý minh chứng.');const p=myProfile();return `<div class="page-head compact"><p class="eyebrow">HỒ SƠ / MINH CHỨNG</p><h1>Việc bạn đã làm</h1><p>Dự án, sản phẩm hoặc trải nghiệm đều có thể được ghi lại. Xác minh do bên được phân quyền thực hiện.</p></div><div class="detail-layout"><div>${panel('Dự án và minh chứng',`${p.evidence.map(e=>`<article class="evidence"><h3>${esc(e.title)}</h3><p>${esc(e.role)} · ${esc(e.result||e.description||'')}</p>${badge(evidenceLabel(e.status))}<div class="row-actions">${e.status==='unverified'?btn('Gửi chờ xác minh','evidence-pending',e.id,'link-button'):''}${btn('Sửa','edit-evidence',e.id,'link-button')}${btn('Xóa','remove-evidence',e.id,'link-button danger')}</div></article>`).join('')||'<p>Chưa có minh chứng. Đây không phải điều kiện để tìm cơ hội.</p>'}`)}</div><aside>${panel('Thêm trải nghiệm',`<form id="evidence-form" novalidate>${field('title','Tên dự án / sản phẩm','',true)}${field('role','Vai trò của bạn','',true)}${area('description','Nhiệm vụ đã làm')}${field('result','Kết quả')}${field('url','Đường dẫn (tùy chọn)')}<button class="btn primary">Lưu minh chứng</button></form>`)}</aside></div>${panel('CV mẫu',`<p>Chỉ lưu tên tệp trong trình duyệt. Không tải tệp lên server, không trích xuất OCR thật và không lưu nội dung CV.</p><label for="cv-file">Chọn CV mẫu</label><input id="cv-file" type="file" accept=".pdf,.doc,.docx"><p>${p.cvName?`Đã chọn: ${esc(p.cvName)} · ${Math.ceil((p.cvSize||0)/1024)} KB · ${esc(p.cvType||'Không xác định')}`:'Chưa chọn tệp.'}</p>${ui.cvUrl?`<p><a class="inline-link" href="${ui.cvUrl}" target="_blank" rel="noopener">Xem tệp vừa chọn →</a></p>`:''}<p>${href('/tuhoso/profile/edit','Nhập thông tin thủ công →','inline-link')}</p>`)}`;}
function sharing(){if(me().role!=='candidate')return access('Chỉ ứng viên đặt quyền chia sẻ hồ sơ.');const p=myProfile();return `<div class="page-head compact"><p class="eyebrow">QUYỀN RIÊNG TƯ</p><h1>Bạn chọn cách chia sẻ</h1><p>Tạm ẩn không xóa hồ sơ hoặc lịch sử kết nối đã có.</p></div><form id="sharing-form" class="panel narrow"><div class="field"><label for="scope">Phạm vi hồ sơ</label><select id="scope" name="scope"><option value="public" ${p.scope==='public'?'selected':''}>Công khai</option><option value="members" ${p.scope==='members'?'selected':''}>Thành viên</option><option value="private" ${p.scope==='private'?'selected':''}>Riêng tư</option></select></div><p class="fine">public = công khai; members = thành viên demo; private = chỉ bạn. Liên hệ không xuất hiện công khai ở mọi chế độ.</p><label class="check"><input type="checkbox" name="visible" ${p.visible?'checked':''}><span>Cho phép hồ sơ xuất hiện trong tìm kiếm và gợi ý</span></label><label class="check"><input type="checkbox" name="shareContact" ${p.shareContact?'checked':''}><span>Cho phép chia sẻ email sau khi hai bên đồng ý trao đổi</span></label><div class="actions"><button class="btn primary">Lưu lựa chọn</button>${href('/tuhoso/profile','Xem trước hồ sơ','btn secondary')}</div></form>`;}
function recommendedJobs(){if(me().role!=='candidate')return access('Gợi ý cơ hội dành cho ứng viên.');const p=myProfile(),arr=d().jobs.filter(j=>j.status==='published').sort((a,b)=>match(b,p).score-match(a,p).score);return `<div class="page-head"><p class="eyebrow">TỪ KHO VIỆC LÀM</p><h1>Cơ hội có thể phù hợp</h1><p>Gợi ý tính từ kỹ năng, hình thức và khu vực bạn đã nhập. Bạn quyết định có gửi đề nghị hay không.</p></div><div class="cards two">${arr.map(j=>`<div>${jobCard(j,true)}<div class="recommend-foot"><span>Điểm phù hợp mô phỏng: <strong>${match(j,p).score}</strong></span>${href('/khovieclam/opportunity/'+j.id,'Xem lý do phù hợp →','inline-link')}</div></div>`).join('')}</div>`;}
function applyPage(id){if(me().role!=='candidate')return access('Chỉ ứng viên gửi đề nghị ứng tuyển.');const j=job(id),p=myProfile();if(!j)return notFound();return `<div class="crumb">${href('/khovieclam/opportunity/'+id,'Chi tiết cơ hội')} / Ứng tuyển</div><div class="page-head compact"><p class="eyebrow">GỬI ĐỀ NGHỊ ỨNG TUYỂN</p><h1>${esc(j.title)}</h1><p>Doanh nghiệp sẽ nhận lời nhắn và phần hồ sơ bạn cho phép chia sẻ.</p></div>${panel('Hồ sơ gửi đi',`<p><strong>${esc(p.name)}</strong> · ${esc(p.headline)}</p><p>Kỹ năng: ${esc(p.skillItems.map(s=>s.name).join(', ')||'Chưa bổ sung')}</p>${href('/tuhoso/profile','Xem hồ sơ của tôi →','inline-link')}`)}<form id="apply-form" data-job="${id}" class="panel narrow">${area('message','Lời nhắn','Tôi muốn tìm hiểu và tham gia cơ hội này.',true)}<label class="check"><input type="checkbox" name="shareContact" ${p.shareContact?'checked':''}><span>Cho phép chia sẻ email sau khi hai bên đồng ý trao đổi</span></label><div class="actions"><button class="btn primary">Gửi đề nghị ứng tuyển</button>${href('/khovieclam/opportunity/'+id,'Hủy','btn secondary')}</div></form>`;}
function homeHub(){return hero('TA.CARE / TALENT ACTIVATION & CAREER ECOSYSTEM','Năng lực được nhìn thấy. Cơ hội được kết nối.','TA.CARE nối nhu cầu công việc với hồ sơ năng lực, giúp hai phía hiểu vì sao phù hợp và tự quyết định bước tiếp theo.',`${href('/tacare/dashboard','Vào không gian của tôi','btn primary')}${href('/tacare/matching','Khám phá sự phù hợp','btn secondary')}`,`<div class="bridge"><div><span class="bridge-dot blue"></span><strong>Năng lực</strong><small>Tủ Hồ Sơ</small></div><div class="bridge-line"><span>Hiểu nhau để kết nối</span></div><div><span class="bridge-dot green"></span><strong>Cơ hội</strong><small>Kho Việc Làm</small></div></div>`)+`<section class="section-heading"><div><p class="eyebrow">MỘT HÀNH TRÌNH LIÊN TỤC</p><h2>Từ điều đã làm đến bước tiếp theo</h2></div></section><div class="steps"><div><span>01</span><h3>Ghi lại năng lực</h3><p>Kỹ năng, dự án, kết quả và điều bạn muốn phát triển.</p>${href('/tuhoso','Khám phá Tủ Hồ Sơ →','inline-link')}</div><div><span>02</span><h3>Làm rõ cơ hội</h3><p>Công việc, yêu cầu và điều kiện được trình bày dễ hiểu.</p>${href('/khovieclam','Khám phá Kho Việc Làm →','inline-link')}</div><div><span>03</span><h3>Trao đổi có căn cứ</h3><p>Điểm phù hợp đi kèm lý do và khoảng còn thiếu.</p>${href('/tacare/matching','Xem cách ghép nối →','inline-link')}</div></div><p class="notice-inline">MPU/SPU, TA.VES, TA.MES và Điều Hành Online là nguồn ngữ cảnh dự kiến; bản thử chưa tích hợp các hệ này.</p>`;}
function hubDashboard(){const u=me(),requests=myRequests(),pending=requests.filter(r=>r.status==='pending'),notes=d().notifications.filter(n=>n.userId===u.id&&!n.read),isBiz=u.role==='business',p=u.role==='candidate'?myProfile():null,related=isBiz?myJobs().filter(j=>j.status==='published').length:p?d().jobs.filter(j=>j.status==='published'&&match(j,p).score>=60).length:d().jobs.filter(j=>j.status==='published').length;return `<div class="page-head"><p class="eyebrow">KHÔNG GIAN KẾT NỐI</p><h1>Chào ${esc(u.name)}</h1><p>${isBiz?'Theo dõi nhu cầu, hồ sơ và các cuộc trao đổi của tổ chức.':u.role==='candidate'?'Theo dõi cơ hội, lời mời và bước phát triển tiếp theo.':'Tổng quan dữ liệu demo của hệ sinh thái.'}</p></div><div class="metrics">${metric(related,isBiz?'Tin đang hiển thị':'Cơ hội liên quan')}${metric(pending.length,'Kết nối đang chờ')}${metric(notes.length,'Thông báo chưa đọc')}${metric(requests.filter(r=>r.status==='accepted').length,'Đồng ý trao đổi')}</div><div class="dashboard-grid">${panel('Hành động tiếp theo',`<ul class="link-list"><li>${href(isBiz?'/khovieclam/dashboard':'/tuhoso/dashboard',isBiz?'Quản lý tin của tổ chức':'Hoàn thiện hồ sơ của bạn')}</li><li>${href('/tacare/matching','Xem lý do phù hợp')}</li><li>${href('/tacare/connections','Xem đề nghị và lời mời')}</li><li>${href('/tacare/notifications','Mở trung tâm thông báo')}</li></ul>`)}${panel('Kết nối gần đây',requests.slice(0,3).map(r=>`<div class="mini-row">${href('/tacare/connection/'+r.id,esc(job(r.jobId)?.title||r.jobId))}${badge(requestStatus(r.status),r.status)}</div>`).join('')||'<p>Chưa có kết nối.</p>')}</div>`;}
function matchingPage(){const u=me(),all=d();const query=new URLSearchParams(location.search),jobId=query.get('job');let selectedJob=jobId?job(jobId):null;if(u.role==='business'&&!selectedJob)selectedJob=myJobs().find(j=>j.status==='published');if(u.role==='candidate'){const p=myProfile(),arr=all.jobs.filter(j=>j.status==='published').sort((a,b)=>match(b,p).score-match(a,p).score);return `<div class="page-head"><p class="eyebrow">TA.CARE / ĐỐI CHIẾU</p><h1>Vì sao cơ hội này phù hợp?</h1><p>So sánh những gì bạn đã ghi trong hồ sơ với yêu cầu tin. Điểm chỉ là mô phỏng.</p></div>${arr.map(j=>`<article class="match-result"><div class="result-title"><div><p class="eyebrow">${esc(j.type)} · ${esc(org(j.orgId)?.name)}</p><h2>${href('/khovieclam/opportunity/'+j.id,esc(j.title))}</h2></div><div class="score"><strong>${match(j,p).score}</strong><small>Điểm phù hợp<br>mô phỏng</small></div></div>${matchPanel(j,p)}<div class="actions">${href('/tuhoso/apply/'+j.id,'Gửi đề nghị ứng tuyển','btn primary')}${href('/tuhoso/skills','Bổ sung kỹ năng','btn secondary')}</div></article>`).join('')}`;}
 if(u.role==='business'){const jobs=myJobs().filter(j=>j.status==='published');selectedJob=jobs.find(j=>j.id===selectedJob?.id)||jobs[0];if(!selectedJob)return access('Hãy đăng một tin trước khi xem hồ sơ phù hợp.');const ps=eligibleProfiles().sort((a,b)=>match(selectedJob,b).score-match(selectedJob,a).score);return `<div class="page-head"><p class="eyebrow">TA.CARE / ĐỐI CHIẾU</p><h1>Hồ sơ phù hợp với tin của bạn</h1><p>Chỉ hiện hồ sơ cho phép tìm thấy. Xem lý do trước khi mời trao đổi.</p></div><form id="match-select" class="panel compact-panel">${selectNamed('job','Chọn tin',jobs,selectedJob.id,true)}<button class="btn primary">Xem hồ sơ</button></form><div class="match-list">${ps.map(p=>`<article class="match-result">${profileCard(p,selectedJob)}${matchPanel(selectedJob,p)}<div class="actions">${href('/tuhoso/profile/'+p.id,'Xem hồ sơ được chia sẻ','btn secondary')}${href('/tacare/invite/'+selectedJob.id+'/'+p.id,'Mời trao đổi','btn primary')}</div></article>`).join('')}</div>`;}
 return `<div class="page-head"><h1>Đối chiếu mô phỏng</h1><p>Chọn tài khoản doanh nghiệp hoặc ứng viên trong thanh công cụ demo.</p></div>`;}
function invitePage(jobId,profileId){const j=job(jobId),p=profile(profileId);if(me().role!=='business'||!j||!p||j.orgId!==me().orgId)return access('Chọn tin và hồ sơ thuộc quyền phù hợp để mời.');return `<div class="page-head compact"><p class="eyebrow">LỜI MỜI TRAO ĐỔI</p><h1>Mời ${esc(p.name)}</h1><p>Về tin: ${esc(j.title)}. Chấp nhận lời mời chỉ đồng ý trao đổi.</p></div>${panel('Lý do phù hợp',matchPanel(j,p))}<form id="invite-form" data-profile="${p.id}" data-job="${j.id}" class="panel narrow">${area('message','Lời nhắn','Chúng tôi muốn mời bạn trao đổi về cơ hội này.',true)}<button class="btn primary">Gửi lời mời</button></form>`;}
function connectionsPage(){const rows=myRequests();return `<div class="page-head"><p class="eyebrow">${root()==='tacare'?'TA.CARE':root()==='khovieclam'?'KHO VIỆC LÀM':'TỦ HỒ SƠ'} / KẾT NỐI</p><h1>Đề nghị và lời mời</h1><p>Mỗi kết nối liên quan trực tiếp một tin và một hồ sơ. Đồng ý trao đổi chưa phải quyết định tuyển dụng.</p></div><div class="connection-list">${rows.map(r=>`<article class="connection-row"><div><p class="eyebrow">${r.type==='application'?'ĐỀ NGHỊ ỨNG TUYỂN':'LỜI MỜI TRAO ĐỔI'} · ${r.id}</p><h2>${href('/tacare/connection/'+r.id,esc(job(r.jobId)?.title||'Tin đã xóa'))}</h2><p>${esc(profile(r.profileId)?.name||r.snapshot?.name)} · ${r.senderId===me().id?'Bạn đã gửi':'Bạn đã nhận'}</p></div><div>${badge(requestStatus(r.status),r.status)}<p>${href('/tacare/connection/'+r.id,'Xem chi tiết →','inline-link')}</p></div></article>`).join('')||'<div class="empty">Chưa có kết nối nào.</div>'}</div>`;}
function connectionDetail(id){const r=myRequests().find(x=>x.id===id);if(!r)return access('Kết nối này không thuộc tài khoản demo của bạn.');const j=job(r.jobId),p=profile(r.profileId),receiver=r.receiverId===me().id,sender=r.senderId===me().id,accepted=r.status==='accepted',sharedName=p?.visible&&p.scope!=='private'?p.name:r.snapshot?.name||'Hồ sơ đã chia sẻ';const consent=p?.shareContact&&(r.type==='invitation'||r.shareContact)&&accepted;return `<div class="crumb">${href('/tacare/connections','Kết nối')} / ${r.id}</div><div class="page-head compact"><p class="eyebrow">${r.type==='application'?'ĐỀ NGHỊ ỨNG TUYỂN':'LỜI MỜI TRAO ĐỔI'} · ${esc(r.id)}</p><h1>${esc(j?.title||'Tin đã xóa')}</h1><p>${badge(requestStatus(r.status),r.status)} · ${esc(r.created)}</p></div><div class="detail-layout"><div>${panel('Nội dung đề nghị',`<p>${esc(r.message||'Không có lời nhắn.')}</p><p><strong>Bên gửi:</strong> ${esc(user(r.senderId)?.name||'Tài khoản demo')}</p><p><strong>Bên nhận:</strong> ${esc(user(r.receiverId)?.name||'Tài khoản demo')}</p>${j?.status==='closed'?'<p class="notice-inline">Tin đã đóng; lịch sử đề nghị vẫn được giữ.</p>':''}<div class="actions">${receiver&&r.status==='pending'?`${btn('Đồng ý trao đổi','respond',r.id,'btn primary',`data-status="accepted"`)}${btn('Từ chối','respond',r.id,'btn secondary',`data-status="declined"`)}`:''}${sender&&r.status==='pending'?btn('Hủy đề nghị','cancel-request',r.id,'btn secondary'):''}</div>`)}${panel('Lịch sử',`<ol class="timeline">${r.history.map(x=>`<li>${esc(x)}</li>`).join('')}</ol>`)}${accepted?panel('Cập nhật kết quả sau trao đổi',`<form id="feedback-form" data-request="${r.id}">${select('result','Tình trạng',['Đã trao đổi','Đang xem xét','Tham gia cơ hội','Không tiếp tục'],'',true)}${area('note','Ghi chú / phản hồi')}<button class="btn primary">Lưu kết quả trao đổi</button></form>${d().feedback.filter(f=>f.requestId===r.id).map(f=>`<div class="evidence"><strong>${esc(f.result)}</strong> · ${esc(user(f.userId)?.name)}<p>${esc(f.note)}</p></div>`).join('')}`):''}</div><aside>${panel('Dữ liệu liên quan',`<p><strong>Hồ sơ:</strong> ${esc(sharedName)}</p><p>${esc(r.snapshot?.headline||p?.headline||'')}</p><p>Kỹ năng đã chia sẻ: ${esc(r.snapshot?.skills?.join(', ')||p?.skillItems.map(s=>s.name).join(', ')||'Chưa có')}</p><p><strong>Liên hệ:</strong> ${consent?esc(p?.email||'Chưa cung cấp'):'Được giữ riêng cho đến khi hai bên đồng ý trao đổi và chủ hồ sơ cho phép.'}</p><div class="actions vertical">${j?href('/khovieclam/opportunity/'+j.id,'Xem tin gốc','btn secondary'):''}${p&&p.visible&&p.scope!=='private'?href('/tuhoso/profile/'+p.id,'Xem hồ sơ được chia sẻ','btn secondary'):''}</div>`)}</aside></div>`;}
function notificationsPage(){const arr=d().notifications.filter(n=>n.userId===me().id);return `<div class="page-head"><p class="eyebrow">TA.CARE / THÔNG BÁO</p><h1>Thông báo của bạn</h1><p>Thay đổi đề nghị, lời mời và tin được cập nhật trong cùng dữ liệu demo.</p></div><div class="connection-list">${arr.map(n=>`<article class="notification ${n.read?'read':'unread'}"><div><p>${esc(n.message)}</p><small>${n.read?'Đã đọc':'Chưa đọc'}</small></div><div class="actions">${n.requestId?href('/tacare/connection/'+n.requestId,'Mở kết nối','btn secondary'):''}${!n.read?btn('Đánh dấu đã đọc','mark-read',n.id,'btn secondary'):''}</div></article>`).join('')||'<div class="empty">Chưa có thông báo.</div>'}</div>`;}
function notFound(){return `<div class="empty"><h1>Không tìm thấy màn hình</h1><p>Đường dẫn này không thuộc bản thử.</p>${href('/tacare','Về TA.CARE','btn primary')}</div>`;}
function access(txt){return `<div class="empty"><h1>Chưa thể thực hiện</h1><p>${txt}</p>${href('/tacare/dashboard','Về tổng quan','btn primary')}</div>`;}
function route(){const parts=path().split('/').filter(Boolean),[site,section,id,tail]=parts;if(site==='khovieclam'){if(!section)return homeJobs();if(section==='opportunities')return listJobs();if(section==='opportunity')return detailJob(id);if(section==='dashboard')return dashboardJobs();if(section==='job')return jobForm(id);if(section==='candidates')return candidateSearch();if(section==='requests')return connectionsPage();}if(site==='tuhoso'){if(!section)return homeProfile();if(section==='register')return register();if(section==='dashboard')return profileDashboard();if(section==='profile')return id==='edit'?editProfile():profilePage(id);if(section==='skills')return skillsPage();if(section==='evidence')return evidencePage();if(section==='sharing')return sharing();if(section==='opportunities')return recommendedJobs();if(section==='apply')return applyPage(id);if(section==='requests')return connectionsPage();}if(site==='tacare'){if(!section)return homeHub();if(section==='dashboard')return hubDashboard();if(section==='matching')return matchingPage();if(section==='invite')return invitePage(id,tail);if(section==='connections')return connectionsPage();if(section==='connection')return connectionDetail(id);if(section==='notifications')return notificationsPage();}return notFound();}
function render(){document.title=`${brand[root()]?.name||'TA.CARE'} · Bản thử`;shell(route());}
function values(form){return Object.fromEntries(new FormData(form).entries());}
function showErrors(form,checks){let first=null;for(const [name,msg] of Object.entries(checks)){const el=form.elements.namedItem(name);if(!el)continue;el.setAttribute('aria-invalid','true');el.setAttribute('aria-describedby',`${name}-error`);const e=form.querySelector(`#${name}-error`);if(e)e.textContent=msg;first??=el;}if(first){first.focus();return false;}return true;}
function requireFields(form,names){const errors={};for(const name of names){const el=form.elements.namedItem(name);if(el&&!String(el.value||'').trim())errors[name]='Vui lòng điền trường này.';}if(!showErrors(form,errors))return false;return true;}
function jobValues(form){const v=values(form);return {title:v.title?.trim(),sector:v.sector,type:v.type,mode:v.mode,location:v.location?.trim(),experience:v.experience,schedule:v.schedule?.trim(),start:v.start,deadline:v.deadline,quantity:Number(v.quantity),pay:v.pay?.trim()||'Chưa công bố',outcome:v.outcome?.trim(),description:v.description?.trim(),required:new FormData(form).getAll('required'),preferred:new FormData(form).getAll('preferred')};}
app.addEventListener('click',e=>{const a=e.target.closest('a[data-link]');if(a){e.preventDefault();go(a.getAttribute('href'));return;}const b=e.target.closest('button[data-action]');if(!b)return;const action=b.dataset.action,id=b.dataset.id;safe(()=>{if(action==='reset'){if(!confirm('Khôi phục toàn bộ dữ liệu demo về ban đầu?'))return;if(ui.cvUrl)URL.revokeObjectURL(ui.cvUrl);ui.cvUrl='';store.reset();ui.filters={};message('Đã khôi phục dữ liệu mẫu.');}
 else if(action==='clear-filters'){ui.filters={};render();}
 else if(action==='sector'){ui.filters={sector:id};go('/khovieclam/opportunities');}
 else if(action==='job-filter'){ui.jobStatusFilter=id;render();}
 else if(action==='job-status'){store.setJobStatus(id,b.dataset.status);message('Đã cập nhật trạng thái tin.');}
 else if(action==='edit-skill'){const item=myProfile().skillItems.find(x=>x.name===id),f=app.querySelector('#skill-form');if(item&&f){f.dataset.original=id;f.elements.name.value=item.name;f.elements.level.value=item.level;f.elements.use.value=item.use;f.querySelector('button').textContent='Lưu kỹ năng';f.scrollIntoView({behavior:'smooth',block:'center'});}return;}
 else if(action==='edit-evidence'){const item=myProfile().evidence.find(x=>x.id===id),f=app.querySelector('#evidence-form');if(item&&f){f.dataset.evidence=id;for(const key of ['title','role','description','result','url'])f.elements[key].value=item[key]||'';f.querySelector('button').textContent='Lưu thay đổi';f.scrollIntoView({behavior:'smooth',block:'center'});}return;}
 else if(action==='remove-skill'){store.removeSkill(id);message('Đã xóa kỹ năng.');}
 else if(action==='remove-evidence'){store.removeEvidence(id);message('Đã xóa minh chứng.');}
 else if(action==='evidence-pending'){store.setEvidencePending(id);message('Minh chứng đang chờ xác minh demo. Chưa được xác minh.');}
 else if(action==='toggle-preview'){ui.profileView=ui.profileView==='owner'?'public':'owner';render();}
 else if(action==='back-preview'){ui.preview=null;render();}

 else if(action==='respond'){store.respondRequest(id,b.dataset.status);message('Đã gửi phản hồi; trạng thái kết nối cập nhật ở cả hai phía.');}
 else if(action==='cancel-request'){store.cancelRequest(id);message('Đã hủy đề nghị đang chờ.');}
 else if(action==='mark-read'){store.markRead(id);message('Đã đánh dấu thông báo là đã đọc.');}});});
app.addEventListener('change',e=>{if(e.target.id==='demo-user'){safe(()=>{if(ui.cvUrl)URL.revokeObjectURL(ui.cvUrl);ui.cvUrl='';store.switchUser(e.target.value);ui.profileView='owner';go('/tacare/dashboard');});}if(e.target.id==='cv-file'){const file=e.target.files?.[0];if(file)safe(()=>{if(ui.cvUrl)URL.revokeObjectURL(ui.cvUrl);ui.cvUrl=URL.createObjectURL(file);store.setCVMeta(file.name,file.size,file.type);message('Chỉ lưu metadata trong trình duyệt; không tải CV lên server.');});}});
app.addEventListener('submit',e=>{e.preventDefault();const f=e.target,v=values(f);safe(()=>{
 if(f.id==='job-filters'){ui.filters=v;render();return;}
 if(f.id==='job-form'){const intent=e.submitter?.value||'draft';if(intent==='publish'&&!requireFields(f,['title','sector','type','mode','location','experience','deadline','description']))return;const values=jobValues(f);if(intent==='publish'&&!values.required.length){f.querySelector('#required-error').textContent='Chọn ít nhất một kỹ năng bắt buộc.';f.querySelector('#required').focus();return;}const dateErrors={};if(values.start&&values.deadline&&values.deadline<values.start)dateErrors.deadline='Hạn nhận đề nghị phải từ ngày bắt đầu trở đi.';if(!Number.isInteger(values.quantity)||values.quantity<1)dateErrors.quantity='Số lượng phải là số nguyên dương.';if(!showErrors(f,dateErrors))return;if(intent==='preview'){ui.preview=values;render();return;}const id=store.saveJob(values,f.dataset.id||null,intent==='publish');ui.preview=null;go('/khovieclam/opportunity/'+id);message(intent==='publish'?'Tin đã được đăng và có trong kho cơ hội.':'Đã lưu bản nháp.');return;}
 if(f.id==='register-form'){if(!requireFields(f,['name']))return;store.createCandidate(v.name);go('/tuhoso/profile/edit');message('Đã tạo tài khoản ứng viên demo. Bây giờ bạn có thể điền hồ sơ.');return;}
 if(f.id==='profile-form'){if(!requireFields(f,['name']))return;store.saveProfile(v);go('/tuhoso/profile');message('Đã lưu hồ sơ.');return;}
 if(f.id==='skill-form'){if(!requireFields(f,['name','level']))return;if(f.dataset.original)store.updateSkill(f.dataset.original,v.name,v.level,v.use);else store.addSkill(v.name,v.level,v.use);message('Đã lưu kỹ năng; gợi ý phù hợp sẽ cập nhật theo.');return;}
 if(f.id==='evidence-form'){if(!requireFields(f,['title','role']))return;if(f.dataset.evidence)store.updateEvidence(f.dataset.evidence,v);else store.addEvidence(v);message('Đã lưu minh chứng. Trạng thái xác minh không tự thay đổi.');return;}
 if(f.id==='sharing-form'){store.setVisibility({scope:v.scope,visible:f.elements.visible.checked,shareContact:f.elements.shareContact.checked});message('Đã cập nhật quyền chia sẻ và khả năng được tìm thấy.');return;}
 if(f.id==='apply-form'){if(!requireFields(f,['message']))return;const id=store.createRequest('application',f.dataset.job,me().profileId,v.message,!!v.shareContact);go('/tacare/connection/'+id);message('Đề nghị đã gửi. Doanh nghiệp sẽ thấy cùng kết nối này.');return;}
 if(f.id==='invite-form'){if(!requireFields(f,['message']))return;const id=store.createRequest('invitation',f.dataset.job||v.jobId,f.dataset.profile,v.message);go('/tacare/connection/'+id);message('Lời mời đã gửi đến ứng viên.');return;}
 if(f.id==='match-select'){go('/tacare/matching?job='+encodeURIComponent(v.job));return;}
 if(f.id==='feedback-form'){if(!requireFields(f,['result']))return;store.addFeedback(f.dataset.request,v.result,v.note||'');message('Đã lưu kết quả trao đổi riêng với trạng thái đề nghị.');return;}
 });});
app.addEventListener('input',e=>{const el=e.target;if(el.matches('[aria-invalid="true"]')){el.removeAttribute('aria-invalid');const error=app.querySelector(`#${el.name}-error`);if(error)error.textContent='';}});
window.addEventListener('popstate',render);
render();
